public final class Balance {
    private final Object lock = new Object();  // dedicated guardian lock
    private long amount;                       // private: reachable only under lock
    private int ops;

    public void credit(long delta) {
        synchronized (lock) { amount += delta; ops++; }
    }
    public long snapshot() {
        synchronized (lock) { return amount; }  // copy out, never return a view
    }
}

