public final class Balance {
    private final Lock lock = new ReentrantLock();
    private long amount;

    public boolean transferIn(long delta, long millis) throws InterruptedException {
        if (!lock.tryLock(millis, TimeUnit.MILLISECONDS)) return false;
        try { amount += delta; return true; }
        finally { lock.unlock(); }   // every path must release
    }
}
